export function moveMe(items) {
  const total = items.reduce((a, b) => a + b, 0);
  const mean = total / items.length;
  const spread = items.map((v) => (v - mean) ** 2);
  return Math.sqrt(spread.reduce((a, b) => a + b, 0) / items.length);
}
export const A = 1;

